{"path":"assets/css/styles.css","content":"/* Earthy warm palette, minimal poetic layout */
:root{
  --bg:#efe8df;
  --muted:#b09a86;
  --accent:#7a4f3a;
  --dark:#2b2b2b;
  --glass:rgba(255,255,255,0.6);
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; color:var(--dark);background:linear-gradient(180deg,var(--bg),#efe6dd) fixed,url('../assets/img/pattern.svg');background-blend-mode:soft-light;padding:0}
.wrap{max-width:1100px;margin:0 auto;padding:2rem}
.site-header{backdrop-filter: blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.3));border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.nav{display:flex;gap:1rem;align-items:center}
.nav a{color:var(--dark);text-decoration:none;padding:0.4rem 0.6rem;border-radius:6px}
.nav a.cta{background:var(--accent);color:#fff}
.nav-toggle{display:none;border:0;background:transparent;font-size:1.2rem}
.hero{padding:4rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:2rem;align-items:center}
.hero-copy .eyebrow{color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin:0}
.hero-copy .title{font-size:2rem;margin:.4rem 0 0}
.lede{color:#49423c}
.actions{margin-top:1rem}
.btn{display:inline-block;padding:.7rem 1rem;border-radius:8px;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{border:1px solid rgba(0,0,0,0.06);background:transparent;color:var(--dark)}
.hero-visual{height:320px;border-radius:12px;overflow:hidden;background:linear-gradient(135deg,rgba(122,79,58,0.08),rgba(122,79,58,0.04));display:flex;align-items:center;justify-content:center}
.pattern-layer{width:100%;height:100%;background-image:linear-gradient(180deg,rgba(255,255,255,0.2),transparent);}
.content-block{padding:3rem 0}
.section-title{font-size:1.1rem;color:var(--accent);margin:0 0 1rem}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.card{background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.5));padding:1rem;border-radius:10px}
.pillars-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.pillar{background:var(--glass);padding:1rem;border-radius:10px;text-align:center}
.pillar .icon{width:40px;height:40px;fill:var(--muted);opacity:0.9}
.muted{background:linear-gradient(180deg,rgba(250,246,243,0.6),transparent)}
.notes-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.note{background:#fff;padding:1rem;border-radius:8px;border-left:4px solid var(--accent)}
.faq-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem}
.faq-item{background:rgba(255,255,255,0.6);padding:1rem;border-radius:8px}
.cta-block{padding:2.5rem 0;background:linear-gradient(180deg,rgba(122,79,58,0.06),transparent);border-top:1px solid rgba(0,0,0,0.02)}
.cta-row{display:flex;align-items:center;justify-content:space-between}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;padding:2rem 0}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);background:transparent}
.credits{text-align:center;padding:1rem;font-size:.85rem;color:var(--muted)}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .pillars-grid{grid-template-columns:1fr}
  .notes-grid{grid-template-columns:1fr}
  .faq-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block}
}
/* small utilities */
.hidden{display:none}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var btn = document.getElementById('navToggle');
  var nav = document.getElementById('mainNav');
  btn && btn.addEventListener('click',function(){
    if(nav.style.display==='flex'){nav.style.display='none';btn.innerText='☰';}
    else{nav.style.display='flex';nav.style.flexDirection='column';nav.style.gap='1rem';btn.innerText='✕';}
  });

  // Footer year
  var y = new Date().getFullYear();
  var el = document.getElementById('year');
  if(el) el.textContent = y;

  // Simple focus trap for modals (placeholder for booking)
  window.addEventListener('keydown', function(e){
    if(e.key==='Escape'){ // close mobile nav if open
      if(nav && nav.style.display==='flex' && window.innerWidth<=900){nav.style.display='none';btn.innerText='☰';}
    }
  });
})();"} 
